function gateDiagnostic({label,hint,solution,done=true}){const rows=[...document.querySelectorAll('.obj-name')].filter(e=>e.textContent===label),card=rows.length===1?rows[0].closest('.obj-content'):null,buttons=card?[...card.querySelectorAll('button')]:[];return {visible:document.visibilityState==='visible',uniqueCard:rows.length===1,expected:{hint,solution,done},actual:{hint:buttons.some(e=>['Hint','Hide hint'].includes(e.textContent.trim())),solution:buttons.some(e=>e.textContent.trim()==='Solution'),done:Boolean(card&&getComputedStyle(card.parentElement).borderTopColor==='rgb(34, 197, 94)')}};}
