function cardReady({label,hint,solution,done=true}){const rows=[...document.querySelectorAll('.obj-name')].filter(x=>x.textContent===label);if(rows.length!==1)return false;const c=rows[0].closest('.obj-content'),buttons=[...c.querySelectorAll('button')];return buttons.filter(x=>['Hint','Hide hint'].includes(x.textContent.trim())).length===Number(hint)&&buttons.filter(x=>x.textContent.trim()==='Solution').length===Number(solution)&&(!done||getComputedStyle(c.parentElement).borderTopColor==='rgb(34, 197, 94)');}
