function solutionVisible({title,text,admin=false}){const headings=[...document.querySelectorAll(admin?'h2':'h3')].filter(e=>e.textContent===(admin?title:'Solution: '+title));if(headings.length!==1)return false;const header=admin?headings[0].parentElement?.parentElement:headings[0].parentElement;const modal=header?.parentElement;return Boolean(header?.querySelector('button')&&modal?.textContent.includes(text));}
